Input: {"question": "What is the location of the Central Square Historic District?", "original_source_segments": {"D1S1": {"document_number": 1, "doc_id": "ramdocs-0439-37d1eb52c7cb:d00", "start": 0, "end": 178, "text": "Central Square Historic District (Bristol, New Hampshire) The Central Square Historic District of Bristol, New Hampshire, encompasses the central commercial district of the town."}, "D1S2": {"document_number": 1, "doc_id": "ramdocs-0439-37d1eb52c7cb:d00", "start": 179, "end": 340, "text": "The square is a four-sided space near the junction of six roadways in the center of Bristol, just north of the Newfound River and west of the Pemigewasset River."}, "D1S3": {"document_number": 1, "doc_id": "ramdocs-0439-37d1eb52c7cb:d00", "start": 341, "end": 530, "text": "The district includes all of the buildings that are arrayed around the square, as well as one contemporary commercial building located just south of the Newfound River on South Main Street."}, "D1S4": {"document_number": 1, "doc_id": "ramdocs-0439-37d1eb52c7cb:d00", "start": 531, "end": 607, "text": "The district was listed on the National Register of Historic Places in 1983."}, "D1S5": {"document_number": 1, "doc_id": "ramdocs-0439-37d1eb52c7cb:d00", "start": 608, "end": 621, "text": "The center of"}, "D2S1": {"document_number": 2, "doc_id": "ramdocs-0439-37d1eb52c7cb:d01", "start": 0, "end": 197, "text": "Central Square Historic District (Stoneham, Massachusetts) The Central Square Historic District is a historic district encompassing much of the central business district of Stoneham, Massachusetts."}, "D2S2": {"document_number": 2, "doc_id": "ramdocs-0439-37d1eb52c7cb:d01", "start": 198, "end": 470, "text": "It includes the town's largest concentration of 19th and early-20th century commercial architecture, in an area that developed in importance as a commercial center after the construction of the Andover-Medford Turnpike (now Main Street, designated Massachusetts Route 28)."}, "D2S3": {"document_number": 2, "doc_id": "ramdocs-0439-37d1eb52c7cb:d01", "start": 471, "end": 546, "text": "The district was added to the National Register of Historic Places in 1990."}, "D2S4": {"document_number": 2, "doc_id": "ramdocs-0439-37d1eb52c7cb:d01", "start": 547, "end": 651, "text": "The town of Stoneham is located north of the city of Boston, and is now predominantly a commuter suburb."}, "D2S5": {"document_number": 2, "doc_id": "ramdocs-0439-37d1eb52c7cb:d01", "start": 652, "end": 679, "text": "In the mid-19th century the"}, "D3S1": {"document_number": 3, "doc_id": "ramdocs-0439-37d1eb52c7cb:d02", "start": 0, "end": 122, "text": "the 1887 fire station at 25 Lexington Street; it is a brick Queen Anne structure designed by local architect Samuel Patch."}, "D3S2": {"document_number": 3, "doc_id": "ramdocs-0439-37d1eb52c7cb:d02", "start": 123, "end": 209, "text": "It stands next to the 1890 police station building, designed by Hartwell & Richardson."}, "D3S3": {"document_number": 3, "doc_id": "ramdocs-0439-37d1eb52c7cb:d02", "start": 210, "end": 284, "text": "A row of commercial buildings stand across Main Street, facing the common."}, "D3S4": {"document_number": 3, "doc_id": "ramdocs-0439-37d1eb52c7cb:d02", "start": 285, "end": 334, "text": "Many of these were designed by architect Henry W."}, "D3S5": {"document_number": 3, "doc_id": "ramdocs-0439-37d1eb52c7cb:d02", "start": 335, "end": 393, "text": "Hartwell, as was the Music Hall building at 15 Elm Street."}, "D3S6": {"document_number": 3, "doc_id": "ramdocs-0439-37d1eb52c7cb:d02", "start": 394, "end": 451, "text": "Most of these buildings were built between 1880 and 1920."}, "D3S7": {"document_number": 3, "doc_id": "ramdocs-0439-37d1eb52c7cb:d02", "start": 452, "end": 571, "text": "The common itself is a rectangular area about in size, out of which a smaller rectangle has been cut where City Hall is"}}, "original_cards": [{"doc_id": "ramdocs-0439-37d1eb52c7cb:d00", "card_id": "ramdocs-0439-37d1eb52c7cb:d00:c0", "entity": "Central Square Historic District", "scope": "Location", "claim": "The Central Square Historic District is located in Bristol, New Hampshire.", "answer": "Bristol, New Hampshire", "quote": "Central Square Historic District (Bristol, New Hampshire) The Central Square Historic District of Bristol, New Hampshire, encompasses the central commercial district of the town.", "original_document_number": 1}, {"doc_id": "ramdocs-0439-37d1eb52c7cb:d01", "card_id": "ramdocs-0439-37d1eb52c7cb:d01:c0", "entity": "Central Square Historic District", "scope": "Location", "claim": "The Central Square Historic District is a historic district encompassing much of the central business district of Stoneham, Massachusetts.", "answer": "Stoneham, Massachusetts", "quote": "Central Square Historic District (Stoneham, Massachusetts) The Central Square Historic District is a historic district encompassing much of the central business district of Stoneham, Massachusetts.", "original_document_number": 2}], "current_answers": ["Bristol, New Hampshire", "Stoneham, Massachusetts"], "candidate_answers": [{"candidate_id": "R0", "answer": "Bristol, New Hampshire", "origin": "initial"}, {"candidate_id": "R1", "answer": "Stoneham, Massachusetts", "origin": "initial"}]}

